from sympy import primerange
import math

def compute_family1_mod_p(p, num_terms=20000):
    u = [1 % p, 11 % p]
    for i in range(num_terms):
        u.append((6*u[-1] - u[-2]) % p)
    return u

def find_period(u_mod_p):
    target = (u_mod_p[0], u_mod_p[1])
    for i in range(1, len(u_mod_p)-1):
        if (u_mod_p[i], u_mod_p[i+1]) == target:
            return i
    return None

# Collect constraints from primes where few survive
constraints = []
for p in primerange(3, 300):
    u = compute_family1_mod_p(p, 20000)
    period = find_period(u)
    if period is None:
        continue

    pow2_mod_p = set()
    v = 1
    for _ in range(p*2):
        pow2_mod_p.add(v)
        v = (v * 2) % p

    g = math.gcd(12, period)
    possible_n_mods = set()
    for j in range(period // g):
        possible_n_mods.add((2 + 12*j) % period)

    surviving = set()
    for nm in possible_n_mods:
        val = (u[nm] - 1) % p
        if val in pow2_mod_p:
            surviving.add(nm)

    if len(surviving) < len(possible_n_mods) and (2 % period) in surviving:
        constraints.append((period, surviving, p, len(possible_n_mods), len(surviving)))

# Sort by effectiveness (ratio of ruled out)
constraints.sort(key=lambda c: c[4]/c[3])

# Combine constraints one by one, but cap the modulus
current_mod = 12
current_allowed = {2}

for period, surviving, p, orig, surv in constraints:
    if current_mod > 10**12:
        break

    new_mod = math.lcm(current_mod, period)
    if new_mod > 10**15:
        continue

    new_allowed = set()
    for r1 in current_allowed:
        for r2 in surviving:
            g = math.gcd(current_mod, period)
            if (r1 - r2) % g != 0:
                continue
            a = current_mod // g
            m = period // g
            diff = (r2 - r1) % period
            d_val = diff // g
            if diff % g != 0:
                continue
            try:
                a_inv = pow(a, -1, m)
            except ValueError:
                continue
            t0 = (d_val * a_inv) % m
            x = (r1 + current_mod * t0) % new_mod
            new_allowed.add(x)

    current_mod = new_mod
    current_allowed = new_allowed
    print(f"p={p:3d} period={period:3d}: {orig}->{surv} survivors | combined mod={current_mod}, |allowed|={len(current_allowed)}")

print(f"\nFinal modulus: {current_mod}")
print(f"Number of allowed residues: {len(current_allowed)}")
others = sorted([r for r in current_allowed if r != 2])
if others:
    print(f"Non-trivial surviving residues (first 20): {others[:20]}")
    print(f"Smallest non-trivial: n ≡ {others[0]} (mod {current_mod})")
else:
    print("Only n=2 survives!")
